"""Complete rational one-direction bounds for the actual compact source itself."""
from audit_core import *
st=time.time();source=read('actual-source-polynomial.json');nums=[P(z) for z in source['numerators']];den=P(source['denominator']);deg={t:[int(z.degrees()[q]-den.degrees()[q]) for z in nums] for t,q in [('i',0),('j',1),('w',2)]}
base=read('relative-i-completeness-independent-audit.json');hi=base['infinity_gauge'];ideg=[deg['i'][r]-hi[r] for r in range(8)];igrowth=max(3,max(ideg)+1)+max(hi)
jg=read('j-infinity-shear.json');assert jg['status']=='PASS Fuchsian gauge';g=jf(jg['shear_g']);gd=int(g.n.degrees()[1]-g.d.degrees()[1]);jdeg=deg['j'].copy();jdeg[5]=max(jdeg[5],gd+jdeg[3]);jdeg=[jdeg[r]-jg['diagonal_j_powers'][r] for r in range(8)];jgrowth=max(0,max(jdeg)+1)+max(max(jg['diagonal_j_powers']),gd+jg['diagonal_j_powers'][3])
wgrowth=max(0,max(deg['w'])+1)
families=[{'direction':'i','denominator':'i*L','denominator_degree':7,'infinity_growth_bound':igrowth,'numerator_degree_bound':7+igrowth,'screened_bound':12,'source_degrees_in_infinity_gauge':ideg},{'direction':'j','denominator':'j*L','denominator_degree':3,'infinity_growth_bound':jgrowth,'numerator_degree_bound':3+jgrowth,'screened_bound':8,'source_degrees_in_infinity_gauge':jdeg},{'direction':'w','denominator':'L','denominator_degree':18,'infinity_growth_bound':wgrowth,'numerator_degree_bound':18+wgrowth,'screened_bound':20,'source_degrees_in_infinity_gauge':deg['w']}]
for f in families:assert f['numerator_degree_bound']<=f['screened_bound']
write('bare-source-relative-completeness-audit.json',{'status':'PASS','families':families,'finite_argument':'Actual source has denominator j^2*N*Delta, with no i,L,w,T poles. The Delta connection residues are nilpotent and its source pole is simple, so a rational primitive has no Delta poles. At N the source has at most a simple pole and fractional residues allow no primitive pole. At L the source is regular in the v-infinity gauge, allowing raw pole<=1. At i=0 the h gauge allows source pole<=2 and primitive raw pole<=1. At j=0 the source pole<=2 and doubled fractional residues allow primitive pole<=1. At w,T the regular source and noninteger residues allow no primitive poles. No other finite poles are possible.','infinity_spectral_inputs':['relative-i-completeness-independent-audit.json','j-infinity-shear.json','other-direction-infinity.json'],'scope':'Any rational current with only one nonzero compact base component serving the actual source, with arbitrary rational coefficients in the other two base coordinates. Does not exclude coupled currents or the original full problem.','seconds':time.time()-st})
print('PASS bare-source complete degree bounds',[(f['direction'],f['numerator_degree_bound']) for f in families],time.time()-st,flush=True)
